style.css:
@-moz-document domain("claude.ai") {
/* CSS 변수 자체를 덮어쓰기 - 가장 강력 */
    :root {
        --font-serif: 'Egg9TheNeatFont','Pretendard', 'Noto Sans KR', sans-serif !important;
        --font-sans-serif: 'Egg9TheNeatFont','Pretendard', 'Noto Sans KR', sans-serif !important;
        --font-ui-serif: 'Egg9TheNeatFont','Pretendard', 'Noto Sans KR', sans-serif !important;
        --font-user-message: 'Egg9TheNeatFont','Pretendard', 'Noto Sans KR', sans-serif !important;
        --font-claude-message: 'Pretendard', 'Noto Sans KR', sans-serif !important;
        --font-claude-response: 'Pretendard', 'Noto Sans KR', sans-serif !important;
    }

    /* 전체 요소 강제 적용 (코드 블록 제외) */
    html body *:not(code):not(pre):not(kbd):not(samp):not(.font-mono):not([class*="mono"]) {
        font-family: 'Egg9TheNeatFont', 'Pretendard', 'Noto Sans KR', 'Malgun Gothic', sans-serif !important;
    }

    /* Claude 전용 폰트 클래스 직접 타겟팅 */
    .font-claude-response,
    .font-user-message,
    .font-claude-message,
    .font-styrene,
    .font-tiempos,
    .font-serif,
    .font-sans-serif,
    .font-copernicus,
    [class*="font-claude"],
    [class*="font-user"],
    [class*="font-styrene"],
    [class*="font-tiempos"],
    [class*="font-copernicus"] {
        font-family: 'Pretendard', 'Noto Sans KR', sans-serif !important;
    }

    /* 입력창 */
    div[contenteditable="true"],
    .ProseMirror,
    textarea {
        font-family: 'Egg9TheNeatFont', 'Pretendard', 'Noto Sans KR', sans-serif !important;
    }

    /* 코드 블록은 따로 */
    code, pre, kbd, samp,
    .font-mono,
    [class*="font-mono"] {
        font-family: 'D2Coding', 'JetBrains Mono', 'Consolas', monospace !important;
    }
}
